def find_best_app(script_info, module):
    """Given a module instance this tries to find the best possible
    application in the module or raises an exception.
    """
    from . import Flask
    for attr_name in ('app', 'application'):
        app = getattr(module, attr_name, None)
        if isinstance(app, Flask):
            return app
    matches = [v for k, v in iteritems(module.__dict__) if isinstance(v, Flask)]
    if len(matches) == 1:
        return matches[0]
    elif len(matches) > 1:
        raise NoAppException('Auto-detected multiple Flask applications in module "{module}". Use "FLASK_APP={module}:name" to specify the correct one.'.format(module=module.__name__))
    for attr_name in ('create_app', 'make_app'):
        app_factory = getattr(module, attr_name, None)
        if callable(app_factory):
            try:
                app = check_factory_for_script_info_and_call(app_factory, script_info)
                if isinstance(app, Flask):
                    return app
            except TypeError:
                raise NoAppException('Auto-detected "{callable}()" in module "{module}", but could not call it without specifying arguments.'.format(callable=attr_name, module=module.__name__))
    raise NoAppException('Failed to find application in module "{module}". Are you sure it contains a Flask application? Maybe you wrapped it in a WSGI middleware.'.format(module=module.__name__))

