def _calc_zeta(self, j: int, neighbors: np.ndarray, distances: np.ndarray, vectors: np.ndarray, params) -> float:
    """Calculate ``zeta_ij``."""
    abs_rij = distances[j]
    zeta = 0.0
    for k in range(len(neighbors)):
        if k == j:
            continue
        abs_rik = distances[k]
        if abs_rik > params.R + params.D:
            continue
        costheta = np.dot(vectors[j], vectors[k]) / (abs_rij * abs_rik)
        fc_ik = self._calc_fc(abs_rik, params.R, params.D)
        g_theta = self._calc_gijk(costheta, params)
        arg = (params.lambda3 * (abs_rij - abs_rik)) ** params.m
        if arg > _MAX_EXP_ARG:
            ex_delr = 1e+30
        elif arg < _MIN_EXP_ARG:
            ex_delr = 0.0
        else:
            ex_delr = np.exp(arg)
        zeta += fc_ik * g_theta * ex_delr
    return zeta

