def _gcd_interpolate(h: MPZ | smp[MPZ], x: MPZ, n: int, order: MonomialOrder) -> smp[MPZ]:
    """Interpolate polynomial GCD from integer GCD."""
    f: smp[MPZ] = {}
    i = 0
    if isinstance(h, dict):
        while h:
            g = smp_trunc_ground(h, x, n - 1, ZZ)
            _smp_isub(h, g, n - 1, ZZ)
            _smp_iquo_ground(h, x, n - 1, ZZ)
            if g:
                for monom, coeff in g.items():
                    f[(i,) + monom] = coeff
            i += 1
    else:
        while h:
            c = h % x
            if c > x // 2:
                c -= x
            h = (h - c) // x
            if c:
                f[i,] = c
            i += 1
    if smp_LC(f, n, ZZ, order) < 0:
        return smp_neg(f, n, ZZ)
    else:
        return f

