def justify(self, console: 'Console', width: int, align: Literal['none', 'left', 'center', 'right', 'full']='left') -> None:
    """Pad each line with spaces to a given width.

        Args:
            width (int): Number of characters per line.

        """
    from .text import Text
    if align == 'left':
        for line in self._lines:
            line.set_length(width)
    elif align == 'center':
        for line in self._lines:
            line.rstrip()
            line.pad_left((width - cell_len(line.text)) // 2)
            line.pad_right(width - cell_len(line.text))
    elif align == 'right':
        for line in self._lines:
            line.pad_left(width - cell_len(line.text))
    elif align == 'full':
        for line_index, line in enumerate(self._lines):
            if line_index == len(self._lines) - 1:
                break
            words = line.split(' ')
            words_size = sum((cell_len(word.text) for word in words))
            num_spaces = len(words) - 1
            spaces = [1 for _ in range(num_spaces)]
            index = 0
            if spaces:
                while words_size + num_spaces < width:
                    spaces[len(spaces) - index - 1] += 1
                    num_spaces += 1
                    index = (index + 1) % len(spaces)
            tokens: List[Text] = []
            index = 0
            for index, (word, next_word) in enumerate(zip_longest(words, words[1:])):
                tokens.append(word)
                if index < len(spaces):
                    if next_word is None:
                        space_style = Style()
                    else:
                        style = word.get_style_at_offset(console, -1)
                        next_style = next_word.get_style_at_offset(console, 0)
                        space_style = style if style == next_style else line.style
                    tokens.append(Text(' ' * spaces[index], style=space_style))
                index += 1
            self[line_index] = Text('').join(tokens)

