                        activeConsole.clearConsole();
                        activeConsole.setName(name);
                        console = activeConsole;
                        break;
                    }
                }
            }
        }
        if (console == null) {
            console = new ScriptConsole(name, null);
            ConsolePlugin.getDefault().getConsoleManager().addConsoles(new IConsole[] { console });
